#include "ui/ContextActionSystem.h"
namespace subspace {
std::vector<ContextAction> ContextActionSystem::Resolve(const InteractionContext& c) const {std::vector<ContextAction>a;auto add=[&](const char*id,const char*label,bool e=true,const char*r=""){a.push_back({id,label,e,r});};switch(c.kind){case ContextObjectKind::EmptySpace:add("move","Move Here");add("align","Align Here");add("hold","Hold Position");break;case ContextObjectKind::HostileShip:add("approach","Approach");add("orbit","Orbit");add("range","Keep At Range");add("lock","Lock Target",c.targetable,"Target unavailable");add("engage","Engage",c.targetable,"Target unavailable");if(c.capturable)add("takeover","Take Over Ship",c.disabled,"Disable/secure the vessel before takeover");if(c.fleetAvailable)add("fleet_engage","Fleet: Engage Target");break;case ContextObjectKind::Asteroid:add("approach","Approach");add("orbit","Orbit");add("mine","Mine",c.mineable,"No compatible mining system");if(c.fleetAvailable)add("fleet_mine","Fleet: Mine Cluster",c.mineable,"No mining-capable wing ship");break;case ContextObjectKind::Station:add("approach","Approach");add("align","Align");add("vector","Vector To");add("dock","Request Dock",c.dockable,"Docking unavailable");add("info","Information");break;case ContextObjectKind::Planet:case ContextObjectKind::Moon:add("vector","Vector To Orbit");add("survey","Survey",c.discovered,"Insufficient scan solution");add("info","Information");break;case ContextObjectKind::Wreck:add("approach","Approach");add("salvage","Salvage",c.salvageable,"No salvage equipment");break;case ContextObjectKind::MapDestination:add("vector","Vector To",c.discovered,"Destination unresolved");add("info","Information");break;case ContextObjectKind::Hex:add("construct","Construct");add("route","Establish Logistics Route");add("survey","Survey Region");break;case ContextObjectKind::StationModule:add("inspect","Inspect");add("upgrade","Upgrade");add("offline","Offline");add("remove","Remove");break;default:add("approach","Approach");add("vector","Vector To");if(c.capturable)add("takeover","Take Over Ship",c.disabled,"Disable/secure the vessel before takeover");add("info","Information");break;}return a;}
} // namespace subspace
